clasificarGananciaPatrimonialHasta2014 = ({
  derivaDeTransmision,
  fechaAdquisicion,
  fechaTransmision,
}: {
  readonly derivaDeTransmision: boolean
  readonly fechaAdquisicion?: string | undefined
  readonly fechaTransmision?: string | undefined
}): BaseIntegracionGananciaPatrimonialHasta2014 => {
  if (!derivaDeTransmision) {
    return "base-general"
  }

  if (fechaAdquisicion === undefined || fechaTransmision === undefined) {
    return "base-ahorro"
  }

  return fechaTransmision > sumarUnAnioFechaCivilIso(fechaAdquisicion)
    ? "base-ahorro"
    : "base-general"
}

clasificarBaseGanancia = ({
  anio,
  ganancia,
}: {
  readonly anio: AnioFiscal
  readonly ganancia: GananciaPatrimonialTransmision
}): "base-general" | "base-ahorro" =>
  Match.value(anio).pipe(
    Match.when(
      (anio) => anio === 2013 || anio === 2014,
      () =>
        clasificarGananciaPatrimonialHasta2014({
          derivaDeTransmision: true,
          fechaAdquisicion: ganancia.fechaAdquisicion,
          fechaTransmision: ganancia.fechaTransmision,
        })
    ),
    Match.orElse(() => "base-ahorro" as const)
  )

